function PatrolEntryDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local rewardsVo = CfUtils.GetCfVo(AutoIds.IdSetting366, "PatrolDifficultyCoefficientVo", MazeMgr.mazeDifficultyId)
        local rewardsData = {}
        local rewardsId = parse_strings(rewardsVo.showItem)
        for k, v in pairs(rewardsId) do
            table.insert(rewardsData, {
                goodsId = v,
                goodsNum = 0,
            })
        end
        self.CommonGoodsListEnv:FreshBaseUI(rewardsData, nil, nil, false)
        SetButtonAction(self.FontStyleButton, function ()
            if MazeMgr.remainTime > 0 and not MazeMgr.isJoined then --在开启时间内
                GameUtils.Request(
                        Interfaces.MazeSetEnter,
                        {},
                        function(request, response)
                            if checkInt(response.errCode) == 0 then
                                MazeMgr.isJoined = true
                                UIModule.OpenDialog({id = Constants.UITypeIds.PatrolMainDialog,

                                },
                                        {
                                            {id = Constants.UITypeIds.BattleSelection},
                                        }
                                )
                                --UIModule.CloseDialog(self.controller, true)
                            end
                        end
                )
            end
        end)
        SetButtonAction(self.BtnStore, function ()
            StoreUtils.OpenStore(StoreConstants.OpenIds.StoreMaze)
        end)

        if MazeMgr.remainTime > 0 then--在开启时间内
            if MazeMgr.isJoined then
                if MazeMgr.isPassed then
                    if not MazeMgr.isPassedBefore then
                        MazeMgr.isPassedBefore = true
                        GameUtils.Toast(localize("恭喜达成通关"))
                    end
                    self.fontStyleButtonEnv:ResetFontStyle("B16", localize("已完成"))
                    self.TextDesc.text = localize("本次夜间巡逻已完成，辛苦了调查官。请随时保持警惕，等待下一次行动。")
                    CfUtils.PlaySpine(self.SkeletonRole, "Idle_close", true)
                else

                end
            else
                self.TextDesc.text = localize("深夜，人类的情绪容易处于脆弱的状态，因此暴风眼特别调查署建立了夜间巡逻机制，防止傀化事件发生。")
                self.fontStyleButtonEnv:ResetFontStyle("B1", localize("开始巡逻"))
                CfUtils.PlaySpine(self.SkeletonRole, "Idle_open", true)
            end
        else
            self.TextDesc.text = localize("深夜，人类的情绪容易处于脆弱的状态，因此暴风眼特别调查署建立了夜间巡逻机制，防止傀化事件发生。")
            self.fontStyleButtonEnv:ResetFontStyle("B16", localize("未开放"))
            CfUtils.PlaySpine(self.SkeletonRole, "Idle_close", true)
        end
        self.countDownEnv:StartLeftSecond(MazeMgr.remainTime, 3)
    end))
    return coWait
end

function PatrolEntryDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return PatrolEntryDialog